using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SceneReaderProbe {
 public static int Main(string[] a){try{var json=new JavaScriptSerializer();var content=new ContentStore(Path.Combine(a[0],"extension/data/replier/content")).Load("dXWu3pyxmSU");var video=new Video{Id=content.VideoId,Title="200렙 찍자마자 750만원 혼줌작 때려서 만든 미친매물 ㅋㅋㅋㅋㅋㅋㅋ"};var records=new List<object>();foreach(string name in DualCommentService.Models)using(var m=new LocalModel(Path.Combine(a[0],"extension/.runtime/replier-llm"),name)){var planner=new ScenePlanner(m,(b,t)=>{var body=(Dictionary<string,object>)SceneMaterial.Json(json.Serialize(b));var props=CaptionService.Get(CaptionService.Get(body,"format"),"properties");if(name==DualCommentService.Models[1]&&CaptionService.Get(props,"subject")!=null){body["think"]=true;((Dictionary<string,object>)body["options"])["num_predict"]=4096;}return m.Chat(body,t);});try{var materials=planner.Prepare(video,content,CancellationToken.None).GetAwaiter().GetResult();Console.WriteLine(name+"\n"+SceneMaterial.Read(materials.Values.First()).Summary());records.Add(new{model=name,materials=materials});}catch(Exception e){Console.WriteLine(name+" "+e.Message);}m.Unload().GetAwaiter().GetResult();}File.WriteAllText(Path.Combine(a[0],"extension/data/replier-grounded-checks/scene-reader-probe.json"),json.Serialize(records));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
